  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nubest.com/pages/terms-conditions-nubest-brand-ambassador', 'official_site', 'affiliate', 'NuBest''s official ambassador terms state a standard commission of 15% of order value, a 20% follower discount, custom offers up to 25% for individual ambassadors, a $10 payout threshold via Shopify Collabs, and a public social account with at least 1,000 followers required. The terms contain no earnings-cap statement, so commission_cap is unknown; no creator-count evidence was found, so saturation is unknown.', 'verified', now());
