  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nubest.com/pages/nubest-affiliate-program', 'official_site', 'ugc_collab', 'NuBest''s own affiliate page lays out four partner routes — the Ambassador Program for social creators (free products, own discount code, 15-25% commission), TikTok Shop affiliates, an Awin program for websites (up to 10% per its Awin profile), and sponsored campaigns via media kit to partners@nubest.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 13, 14, 13, 7, 4, '{"compensation": "Official terms publish 15% standard with custom offers up to 25% and a low $10 payout threshold; no cap statement appears in the terms, so the cap is unknown.", "contact_access": "A published partnerships email (partners@nubest.com) plus a full official program page \u2014 top band per the rubric.", "credibility": "Established supplement brand with multiple sales channels and a formal, documented ambassador program.", "niche_fit": "Beauty-from-within and hair supplements fit personal-care content, though much of the line is family nutrition rather than beauty \u2014 partial fit for this category.", "opportunity_availability": "Applications are open via the ambassador page, with a 1,000-follower minimum and a public account required.", "ugc_evidence": "A formal ambassador program with free products and creator discount codes, plus separate TikTok Shop and sponsored-campaign routes."}'::jsonb);
