  insert into public.brands (name, website, description, country, status) values ('Cure Hydration', 'https://www.curehydration.com', 'Cure Hydration is a plant-based hydration brand offering electrolyte drink mixes based on the World Health Organization standard for Oral Rehydration Solution (ORS). Its mixes use coconut water and pink Himalayan salt with no added sugar or artificial ingredients. The brand sells direct-to-consumer and through retailers including Target, CVS and GNC.', 'United States', 'published') returning id into bid;
