  insert into public.brands (name, website, description, country, status) values ('Misfits', 'https://eatmisfits.com', 'Misfits is a UK-born plant-based protein bar brand now selling in the US via eatmisfits.com, with plant-based and Stuffed bar ranges. Its new US Sweet Squad affiliate program pays tiered commission, gives followers 20% off, and sends a free welcome box to approved creators with 1,500+ followers.', 'United States', 'published') returning id into bid;
