  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://eatmisfits.com/pages/the-sweet-squad', 'official_site', 'affiliate', 'Official Sweet Squad page: ''20% Commission on every sale through your link'', ''20% off For your followers with your code'', ''Free box To get you started''. Tiers: Level 1 Sweet 20%, Level 2 Sweeter 25% after 10+ sales/month, Level 3 Sweetest 30% after 25+ sales/month. Tracked via Upfluence dashboard. No cap wording on the page, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://eatmisfits.com/pages/the-sweet-squad', 'official_site', 'ugc_collab', 'New-program evidence: ''Bonuses start 1 November 2026 (quarterly bonuses start with January-March 2027)'' and ''The first year covers sales from 1 November 2026 to 31 December 2027'' for the top-seller trip/$6,000 bonus — the US Sweet Squad is newly launching and actively recruiting, requiring only 1,500+ followers on TikTok or Instagram and US residence.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 19, 17, 11, 10, 5, '{"compensation": "Published 20% base rising to 25%/30% by tier, plus $500 monthly / $2,200 quarterly / trip or $6,000 yearly top-seller bonuses; cap not stated, so unknown.", "contact_access": "Open Apply now route via Upfluence on the official page; no public email published.", "credibility": "Detailed official page with program terms, payout timing (15th of second month after 30-day refund window), and #ad disclosure rules.", "niche_fit": "Protein bars/snacks are core to the scope; plant-based bars fit food-drink and wellness audiences.", "opportunity_availability": "Open application now, 1,500+ follower minimum, bonuses starting 1 November 2026.", "ugc_evidence": "Program is built for UGC: filming guide, hooks, content kit, group chat, welcome box, and paid-ad reuse for up to 12 months stated on the official page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('iFungi', 'https://ifungi.com', 'North American mushroom supplement company (offices in Chicago and Vancouver) selling Life Force 7, an organic 7-species fruiting-body mushroom powder that is SGS-tested in Canada at 41.5% beta-glucans, plus PetShrooms 7 for dogs and cats. Its ambassador program has no minimum follower count and reviews applications personally within three business days.', 'United States', 'published') returning id into bid;
