  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'iFungi Ambassador Program (20% commission, no caps, no follower minimum)', 'https://ifungi.com/en-ca/pages/become-an-ifungi-ambassador', 'https://ifungi.com/en-ca/pages/become-an-ifungi-ambassador', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ifungi.com/en-ca/pages/become-an-ifungi-ambassador', 'official_site', 'affiliate', 'Official ambassador page: 20% commission on every order through link or code, 30-day cookie, monthly payouts via Shopify Collabs, free product and a personalised 20% audience discount code. Exact cap wording in the Earn step: ''20% commission on every sale, paid out monthly. No caps, no tiers, no surprises.'' — this explicit ''No caps'' statement is the basis for commission_cap = uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ifungi.com/en-ca/pages/become-an-ifungi-ambassador', 'official_site', 'ugc_collab', 'Program presents as small and actively recruiting: ''NO MIN. Follower count doesn''t matter. Engagement does.'', ''We review every application personally within 3 business days. Most fit-aligned creators are accepted.'', and a named human contact (partners@ifungi.com) — evidence of a small/new program, supporting creator_saturation = low.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 10, 19, 14, 10, 4, '{"compensation": "20% flat with the page explicitly stating ''No caps, no tiers, no surprises.'' \u2014 a verified uncapped program", "contact_access": "Named partnerships email (partners@ifungi.com) published on the official program page plus a Collabs application", "credibility": "SGS lab results published per product and a 30-day money-back guarantee, but a young, small brand", "niche_fit": "7-mushroom blend spanning reishi (calm/sleep), cordyceps and chaga is a direct mushroom/adaptogen fit, with a pet line as a bonus angle", "opportunity_availability": "Open now via Shopify Collabs, no follower minimum, personal review within 3 business days", "ugc_evidence": "Program supplies asset kits, swipe copy and free product for review content, but the brand is small with little independent creator coverage found"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cometeer', 'https://cometeer.com', 'Cometeer is a Massachusetts-based coffee company that brews specialty coffee from partner roasters, flash-freezes it into capsules, and sells it by subscription for melt-to-make drinks at home. Its affiliate program pays commission on first-time customer purchases over $35 tracked by link or promo code.', 'United States', 'published') returning id into bid;
