  insert into public.brands (name, website, description, country, status) values ('Kettle & Fire', 'https://www.kettleandfire.com', 'Kettle & Fire is a US bone broth and soup brand making shelf-stable broths from grass-fed bones and organic ingredients, slow-simmered and positioned for paleo, keto and Whole30 consumers. Its Club Kettle / Kettler Community ambassador program pays 20% commission, with a welcome package, monthly restocks for posting members, early access, and paid campaign opportunities.', 'United States', 'published') returning id into bid;
