  insert into public.brands (name, website, description, country, status) values ('Pink Stork', 'https://pinkstork.com/', 'Pink Stork is a women-owned wellness company making supplements for women through fertility, pregnancy, postpartum and menopause, founded by Amy Upchurch. Its official Affiliates + Ambassadors page runs two tracks: a no-application affiliate program commissionable across pinkstork.com, Amazon and TikTok Shop, and a community ambassador program.', 'United States', 'published') returning id into bid;
