  insert into public.brands (name, website, description, country, status) values ('Momentous', 'https://www.livemomentous.com/', 'Momentous makes science-backed, third-party-tested performance supplements including protein, creatine, collagen, omega-3 and recovery formulas, built around research and NSF Certified for Sport testing. Its official Affiliate & Ambassador Program recruits creators, community experts and publishers, with paid UGC opportunities for creators.', 'United States', 'published') returning id into bid;
