  insert into public.brands (name, website, description, country, status) values ('Primal Kitchen', 'https://www.primalkitchen.com', 'Primal Kitchen is a US pantry brand founded in 2015 making avocado-oil mayo, dressings, sauces, condiments, collagen, and protein bars without dairy, gluten, grains, or artificial sweeteners. It runs a 10% affiliate program via ShareASale/Refersion and a separate Nutrition Collective ambassador program for registered dietitians.', 'United States', 'published') returning id into bid;
