  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://renpho.com/pages/affiliate-program', 'official_site', 'affiliate', 'Official affiliate page: 10% commission, monthly payouts via Impact, plus a Creator Program via Social Snowball. Verbatim cap claims: ''Monthly Payouts, no caps'', ''sustainable, long-term revenue with no caps'', heading ''Your income, uncapped.'', and FAQ ''You earn 10% commission on every sale referred through your unique link or code, with no cap on earnings.''', 'verified', now());
