  insert into public.brands (name, website, description, country, status) values ('Petterm', 'https://petterm.com/', 'Petterm is a pet wellness brand selling supplements and care products for dogs and cats, including hairball control powder for cats, tear stain powder for dogs and cats, and muscle gain soft chews for dogs. Its affiliate page frames the brand around helping pets live a calmer, healthier life and lists products also sold through Chewy.', null, 'published') returning id into bid;
