  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://petterm.com/pages/affiliate', 'official_site', 'affiliate', 'Official Partner Program page: ''Earn 20% on every order your audience places — no caps, no tiers, no surprises.'' FAQ: ''How much can I earn? You earn 20% commission on every qualifying order... There are no caps and no tiered structures — your earnings scale directly with the audience you reach.'' Also: 30-day cookie, $50 minimum payout, no hard follower minimum, open globally, ships internationally.', 'verified', now());
