  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.dutch.com/pages/ambassadors', 'official_site', 'affiliate', 'Official ambassador page: ''Dutch brand ambassadors earn $40 for every new member who signs up through their unique ambassador link'' — a flat $40 per membership (not a percentage, so commission_rate is null), paid monthly, tracked via Impact. No cap or unlimited-earnings statement appears on the fetched page, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.dutch.com/pages/ambassadors', 'official_site', 'ugc_collab', 'Creator-first terms, verbatim: ''There is no audience size requirement... we don''t set hard follower or traffic thresholds'', ''You don''t need your own website to join. Many of our partners create content solely for TikTok, Instagram, or YouTube'', and ambassadors are ''considered for deeper partnerships, including brand campaigns, featured placement, and paid collaborations''. Apply in 5 minutes, approval in 2 days, free Dutch membership for ambassadors who post monthly.', 'verified', now());
