  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 11, 12, 9, 4, '{"compensation": "Published flat $40 per new membership with extra rewards at 10+ referrals, but it is not a percentage rate and no cap statement is published.", "contact_access": "Published affiliates email plus a short ambassador application form linked from the official page.", "credibility": "Licensed-vet telehealth service with 24/7 care positioning and Impact-run tracking and payments.", "niche_fit": "Program is explicitly built for pet creators on TikTok, Instagram and YouTube sharing reviews, adoption and training content.", "opportunity_availability": "No audience size requirement, 5-minute application and 2-day approval stated on the page.", "ugc_evidence": "Ambassador tier includes brand campaigns, featured placement and paid collaborations, plus a monthly posting structure and free membership."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fieldy', 'https://www.fieldy.ai', 'Fieldy, by Field Labs Inc. (founded 2024, headquartered in Delaware), is a wearable AI note taker worn as a pendant or wristband that transcribes in-person conversations and produces summaries, drafts and follow-ups. Its affiliate program is open to review sites, bloggers, newsletter writers and anyone who recommends products to an audience, paying a notably high 25% base rate.', 'United States', 'published') returning id into bid;
