  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fieldy.ai/affiliates', 'official_site', 'affiliate', 'Official page: ''Fieldy Affiliate Program: Earn 25% to 50% per Sale'', ''You earn 25% of the sale amount on every order, rising to 50% as your monthly sales grow'' (25% up to 14 sales/month, 30% at 15-34, 35% at 35-99, 50% at 100+), 30-day credit, paid via Impact. No ''no cap'' / ''unlimited earnings'' statement was found on the fetched page, so commission_cap is unknown.', 'verified', now());
