  insert into public.brands (name, website, description, country, status) values ('TheHues', 'https://thehues.com', 'TheHues sells custom curtains and shades, including blackout panels and made-to-measure woven shades, for home decor lovers, renters and style-conscious shoppers. It describes itself as the independent official site of top Amazon bestseller NICETOWN in window treatments and actively invites content creators and design professionals to collaborate.', null, 'published') returning id into bid;
