  insert into public.brands (name, website, description, country, status) values ('Pocket', 'https://heypocket.com', 'Pocket, built by San Francisco company Open Vision Engineering Inc., is a small AI recorder that magnetically attaches to a phone and turns meetings, calls and conversations into transcripts, summaries, mind maps and action items. Its partner program pays creators and businesses on both device sales and Pro plan subscriptions, with payouts at least every two weeks.', 'United States', 'published') returning id into bid;
