  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://heypocket.com/pages/affiliate', 'official_site', 'affiliate', 'Official page: ''Join the Pocket Partner Program. Recommend Pocket to your audience and earn on every sale: 6% to 12% on Pocket and 12% to 20% on Pro plans, rising as you sell'', ''6-20% commission per referral'', ''30-day cookie duration'', ''2-week payout cycle'', ''For creators and businesses of all sizes'', ''We review each one by hand, usually within days''. No ''no cap'' / ''unlimited earnings'' statement was found, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fieldy.ai/blog/ai-affiliate-programs', 'article', 'affiliate', 'Fieldy comparison checked 14 Nov 2026: Pocket pays ''6% to 12% on the device, 12% to 20% on Pro plans'' via Impact, 30-day cookie, commission held 45 days then paid at least every two weeks once balance reaches $50.', 'publicly_reported', now());
