  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 13, 13, 8, 4, '{"compensation": "Published 6% rate is modest, but the official FAQ explicitly states ''There is no cap on your commission earnings'', lifting it above unknown-cap peers.", "contact_access": "Published named affiliate contact email (mark.moreno@bentgo.com) plus an official application route via ShareASale.", "credibility": "Widely distributed lunch-products brand based in Santa Ana, United States per Beacons, with sustained creator activity.", "niche_fit": "Lunch / meal-prep products are proven UGC formats for kitchen, family, school and office-home creators.", "opportunity_availability": "Open affiliate program with a documented join process in the official FAQ.", "ugc_evidence": "Official FAQ explicitly invites links, banners and product reviews on websites, social media, video channels and email lists; Beacons shows 15 sponsored posts in 12 months."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Steve''s Real Food', 'https://stevesrealfood.com/', 'Steve''s Real Food, in business since 1998, makes all-natural, nutritionally balanced raw pet food for dogs and cats from Cottonwood Heights, Utah. Its affiliate program has three tracks — Social Media, Pet Pro and Veterinary — with social affiliates creating original social content to earn commission on sales through a unique discount link.', 'United States', 'published') returning id into bid;
