  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Superfiliate', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.rawpetfood.com/pages/affiliate.', 'https://www.rawpetfood.com/pages/affiliate', 'needs_review', now());
