  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.rawpetfood.com/pages/affiliate', 'official_site', 'ugc_collab', 'Official affiliate page: ''Social Media Affiliate: Are you a content creator or influencer who loves sharing your love for pets and the food that fuels them? ... can earn commissions from your passion.'' Also Pet Pro and Veterinary affiliate tracks, with an email entry to apply.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://stevesrealfood.com/affiliate-program-terms-and-conditions/', 'official_site', 'affiliate', 'Terms: affiliate ''agrees to create and post original content to social media to promote the Company... and will earn commission on sales made using their unique discount link'' (25% off code for first-time customers); compensation via Superfiliate platform and free product at sign-up after its Raw U course. No percentage commission rate is published in the terms, so rate is null and cap is unknown. Company address: 2034 E Fort Union Blvd, Cottonwood Heights, UT 84121; contact cs@stevesrealfood.com.', 'verified', now());
