  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 8, 11, 8, 4, '{"compensation": "Commission and free product are documented, but no percentage rate is published, so compensation scores low per the rubric.", "contact_access": "Application/email-entry route on the official affiliate page plus a published general email cs@stevesrealfood.com; no dedicated affiliate email found.", "credibility": "Operating since 1998 as an early raw pet food company, per its own site.", "niche_fit": "Raw dog and cat food with a dedicated social-media creator track \u2014 direct fit for raw-feeding UGC creators.", "opportunity_availability": "Three affiliate tracks open for application on the official page.", "ugc_evidence": "Terms require original social content, a brand hashtag and tagging, with free product at sign-up \u2014 strong, documented UGC structure."}'::jsonb);
